package com.chondrimaishrat.elearning.web;
import com.chondrimaishrat.elearning.auth.SessionAccess; import com.chondrimaishrat.elearning.review.ReviewService; import com.chondrimaishrat.elearning.user.UserRole; import jakarta.servlet.http.HttpSession; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class ReviewController {private final ReviewService reviews;private final SessionAccess access;public ReviewController(ReviewService r,SessionAccess a){reviews=r;access=a;} @PostMapping("/courses/review") public String review(@RequestParam Long courseId,@RequestParam int stars,@RequestParam(required=false) String comment,HttpSession s,RedirectAttributes m){try{reviews.add(access.requireRole(s,UserRole.STUDENT),courseId,stars,comment);m.addFlashAttribute("message","Review submitted.");}catch(IllegalArgumentException e){m.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/courses";}}
